export function Media({
  icon,
  size = "md",
  tone,
  children,
  className,
  style,
  ref,
  ...props
}: React.ComponentPropsWithoutRef<"span"> & {
  icon?: IconName;
  size?: "sm" | "md" | number;
  tone?: "ok" | "warn" | "bad" | "info";
} & { ref?: React.Ref<HTMLSpanElement> }) {
  return (
    <span
      ref={ref}
      data-slot="media"
      data-size={typeof size === "number" ? undefined : size}
      data-tone={tone}
      className={cn(
        helperStyles.media,
        itemStyles.media,
        size === "sm" && helperStyles.mediaSmall,
        className
      )}
      style={{ ...(typeof size === "number" ? { width: size, height: size } : {}), ...style }}
      {...props}
    >
      {icon ? (
        <Icon
          name={icon}
          size={size === "sm" || (typeof size === "number" && size <= 28) ? 14 : 18}
        />
      ) : (
        children
      )}
    </span>
  );
}
Media.displayName = "Media";
export function Tile({
  selected,
  title,
  description,
  media,
  children,
  className,
  type = "button",
  ref,
  ...props
}: Omit<React.ComponentPropsWithoutRef<"button">, "title"> & {
  selected?: boolean;
  title?: React.ReactNode;
  description?: React.ReactNode;
  media?: React.ReactNode;
} & { ref?: React.Ref<HTMLButtonElement> }) {
  const inFrame = useInFrame("Tile");
  return (
    <button
      ref={ref}
      type={type}
      data-slot="tile"
      data-in-frame={inFrame || undefined}
      aria-pressed={selected}
      className={cn(helperStyles.tile, className)}
      {...props}
    >
      {media && <span className={itemStyles.lead}>{media}</span>}
      <span className={helperStyles.tileBody}>
        {title !== undefined ? (
          <>
            <span
              className={itemStyles.tileTitle}
              title={typeof title === "string" ? title : undefined}
            >
              {title}
            </span>
            {description && (
              <span className={cn(itemStyles.description, itemStyles.tileDescription)}>
                {description}
              </span>
            )}
            {children}
          </>
        ) : (
          children
        )}
      </span>
      <Icon name={selected ? "check" : "chev-right"} />
    </button>
  );
}
Tile.displayName = "Tile";
